-- +goose Up

CREATE TABLE IF NOT EXISTS timecard (
    tenant_id                tenant_ref   NOT NULL REFERENCES tenant (tenant_id),
    timecard_id              uuid         NOT NULL,
    timecard_key             semantic_key NOT NULL,
    worker_ref               text NOT NULL,
    period_ref               text NOT NULL,
    status                   text NOT NULL DEFAULT 'OPEN',
    effective_from           date         NOT NULL,
    known_at                 timestamptz  NOT NULL,
    recorded_at              timestamptz  NOT NULL DEFAULT now(),

    PRIMARY KEY (tenant_id, timecard_id),
    CONSTRAINT timecard_key_unique UNIQUE (tenant_id, timecard_key),
    CONSTRAINT timecard_status_check CHECK (status IN ('OPEN', 'SUBMITTED', 'APPROVED', 'LOCKED')),
    CONSTRAINT timecard_knowledge_order CHECK (known_at <= recorded_at)
);

CREATE INDEX IF NOT EXISTS timecard_recorded
    ON timecard (tenant_id, recorded_at DESC);

ALTER TABLE timecard ENABLE ROW LEVEL SECURITY;
ALTER TABLE timecard FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON timecard
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
    WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
GRANT SELECT, INSERT, UPDATE ON timecard TO hcmnext_app;

CREATE TABLE IF NOT EXISTS timecard_revision (
    tenant_id                tenant_ref   NOT NULL REFERENCES tenant (tenant_id),
    revision_id              uuid         NOT NULL,
    timecard_id              uuid         NOT NULL,
    revision_sequence        bigint       NOT NULL,
    total_regular_hours      numeric(8,2) NOT NULL DEFAULT 0,
    total_overtime_hours     numeric(8,2) NOT NULL DEFAULT 0,
    lock_state               text NOT NULL DEFAULT 'UNLOCKED',
    known_at                 timestamptz  NOT NULL,
    recorded_at              timestamptz  NOT NULL DEFAULT now(),

    PRIMARY KEY (tenant_id, revision_id),
    CONSTRAINT timecard_revision_revision_positive CHECK (revision_sequence >= 1),
    CONSTRAINT timecard_revision_total_regular_hours_check CHECK (total_regular_hours >= 0),
    CONSTRAINT timecard_revision_total_overtime_hours_check CHECK (total_overtime_hours >= 0),
    CONSTRAINT timecard_revision_knowledge_order CHECK (known_at <= recorded_at),
    FOREIGN KEY (tenant_id, timecard_id) REFERENCES timecard (tenant_id, timecard_id)
);

CREATE INDEX IF NOT EXISTS timecard_revision_recorded
    ON timecard_revision (tenant_id, recorded_at DESC);

CREATE OR REPLACE TRIGGER timecard_revision_append_only
    BEFORE UPDATE OR DELETE ON timecard_revision
    FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

REVOKE UPDATE, DELETE ON timecard_revision FROM PUBLIC;

ALTER TABLE timecard_revision ENABLE ROW LEVEL SECURITY;
ALTER TABLE timecard_revision FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON timecard_revision
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
    WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
GRANT SELECT, INSERT ON timecard_revision TO hcmnext_app;

